def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    # Opponent's full action sequence and recent stats.
    opp = [h[1] for h in history]
    my = [h[0] for h in history]

    total_c = 0
    for a in opp:
        if a == 'C':
            total_c += 1
    total_d = n - total_c

    # Trailing streak of opponent actions.
    last = opp[-1]
    streak = 0
    for a in reversed(opp):
        if a == last:
            streak += 1
        else:
            break

    # Recent window stats (last 12 rounds).
    w = 12 if n >= 12 else n
    recent = opp[n - w:]
    rc = 0
    for a in recent:
        if a == 'C':
            rc += 1
    rd = w - rc

    remaining = 100 - n

    # Detect a highly exploitable always/nearly-always cooperator.
    if total_d == 0:
        if remaining <= 2:
            return 'D'
        # Defect occasionally to harvest while keeping them cooperating.
        if n % 5 == 0:
            return 'D'
        return 'C'
    if total_d <= 1 and n >= 12:
        if remaining <= 3:
            return 'D'
        if n % 4 == 0:
            return 'D'
        return 'C'

    # Against an entrenched defector, defect (nothing to lose).
    if total_c == 0:
        return 'D'

    # Long opponent defect streak: keep defecting while it continues.
    if last == 'D' and streak >= 3:
        return 'D'

    # Recent dominant defection: retaliate.
    if w >= 6 and rd * 2 >= w:
        return 'D'

    # Recent dominant cooperation by a mostly-cooperative opponent: exploit softly.
    if w >= 6 and rc >= w - 1 and total_c * 3 >= n * 2:
        # Exploit near the end.
        if remaining <= 5:
            return 'D'
        if n % 6 == 0:
            return 'D'
        return 'C'

    # If opponent just defected after cooperating, retaliate once (tit-for-tat).
    if last == 'D':
        # Forgive if the opponent was very cooperative overall and this is isolated.
        if streak == 1 and total_c * 4 >= n * 3 and remaining > 4 and n % 7 != 0:
            return 'C'
        return 'D'

    # Opponent cooperated last. If we defected last, return to cooperation.
    if my[-1] == 'D':
        return 'C'

    # End-game exploitation against a mostly-cooperative opponent.
    if remaining <= 3:
        if total_c * 3 >= n * 2:
            return 'D'
        return 'C'

    # Otherwise cooperate.
    return 'C'
